create table if not exists lead_activities(id text primary key,inquiry_id text not null references inquiries(id) on delete cascade,kind text not null,note text,follow_up_at text,created_by text not null references users(id),created_at text not null default current_timestamp);
create table if not exists client_contacts(id text primary key,user_id text references users(id) on delete set null,name text not null,email text not null,phone text,company text,key_date text,renewal_at text,notes text,created_by text not null references users(id),created_at text not null default current_timestamp);
create table if not exists team_profiles(user_id text primary key references users(id) on delete cascade,team_role text not null check(team_role in('owner','designer','developer','freelancer')),active integer not null default 1 check(active in(0,1)));
create table if not exists project_permissions(project_id text not null references projects(id) on delete cascade,user_id text not null references users(id) on delete cascade,can_edit integer not null default 0,can_upload integer not null default 0,can_invoice integer not null default 0,primary key(project_id,user_id));
create table if not exists update_templates(id text primary key,name text not null,title text not null,body text not null,created_by text not null references users(id),created_at text not null default current_timestamp);
create table if not exists onboarding_templates(id text primary key,name text not null unique,active integer not null default 1,created_by text not null references users(id),created_at text not null default current_timestamp);
create table if not exists onboarding_template_items(id text primary key,template_id text not null references onboarding_templates(id) on delete cascade,title text not null,sort_order integer not null default 0);
create table if not exists project_onboarding_items(id text primary key,project_id text not null references projects(id) on delete cascade,title text not null,completed_at text,sort_order integer not null default 0);
create table if not exists intake_responses(id text primary key,project_id text not null references projects(id) on delete cascade,user_id text not null references users(id),answers text not null,submitted_at text not null default current_timestamp);
create table if not exists notification_preferences(user_id text primary key references users(id) on delete cascade,email_updates integer not null default 1,weekly_digest integer not null default 0,message_alerts integer not null default 1,approval_alerts integer not null default 1,updated_at text not null default current_timestamp);
create table if not exists announcements(id text primary key,title text not null,body text not null,created_by text not null references users(id),published_at text not null default current_timestamp);
create table if not exists announcement_reads(announcement_id text not null references announcements(id) on delete cascade,user_id text not null references users(id) on delete cascade,read_at text not null default current_timestamp,primary key(announcement_id,user_id));
create index if not exists lead_activities_inquiry_idx on lead_activities(inquiry_id,created_at desc);
create index if not exists contacts_renewal_idx on client_contacts(renewal_at);
create index if not exists onboarding_project_idx on project_onboarding_items(project_id,sort_order);
